import numpy as np
import pytest

from ai_engineer.ml.lora import LoRALinear, fit
from ai_engineer.ml.numerics import numerical_gradient, relative_error


@pytest.fixture
def task(np_rng):
    """A frozen layer and data generated by that layer plus a rank-2 change."""
    d = 16
    w = np_rng.normal(size=(d, d)) / np.sqrt(d)
    delta = np_rng.normal(size=(d, 2)) @ np_rng.normal(size=(2, d)) / d
    x = np_rng.normal(size=(256, d))
    return w, x, x @ (w + delta)


def test_a_fresh_adapter_changes_nothing(task, np_rng):
    w, x, _ = task
    layer = LoRALinear.wrap(w, rank=4, alpha=4, rng=np_rng)
    assert np.array_equal(layer(x), x @ w)


def test_adapter_gradients_match_numerical_ones(task, np_rng):
    w, x, y = task
    layer = LoRALinear.wrap(w, rank=2, alpha=2, rng=np_rng)
    layer.b = np_rng.normal(size=layer.b.shape)
    x, y = x[:8], y[:8]
    err = layer(x) - y
    grad_a, grad_b = layer.grads(x, 2 * err / err.size)

    def loss(_: np.ndarray) -> float:
        return float(np.mean((layer(x) - y) ** 2))

    assert relative_error(grad_a, numerical_gradient(loss, layer.a)) < 1e-6
    assert relative_error(grad_b, numerical_gradient(loss, layer.b)) < 1e-6


def test_rank_is_capacity(task, np_rng):
    w, x, y = task
    losses = {}
    for rank in (1, 2):
        layer = LoRALinear.wrap(w, rank=rank, alpha=rank, rng=np_rng)
        losses[rank] = fit(layer, x, y, steps=400, lr=0.5)
    assert losses[2][-1] < losses[2][0] / 1000  # rank 2 learns a rank-2 change
    assert losses[1][-1] > losses[2][-1] * 100  # rank 1 cannot


def test_merging_gives_the_same_layer_with_one_matrix(task, np_rng):
    w, x, y = task
    layer = LoRALinear.wrap(w, rank=2, alpha=2, rng=np_rng)
    fit(layer, x, y, steps=50, lr=0.5)
    assert np.allclose(x @ layer.merged(), layer(x))


def test_the_adapter_is_a_small_fraction_of_the_layer(np_rng):
    layer = LoRALinear.wrap(np.zeros((512, 512)), rank=8, alpha=16, rng=np_rng)
    assert layer.trainable == 2 * 512 * 8
    assert layer.trainable / layer.weight.size == pytest.approx(1 / 32)
